style.css:
@-moz-document url-prefix("https://studentweb.vidyamandir.com/learn") {
html, body, * {
    background: #000 !important;
    color: #e0e0e0 !important;
    border-color: #333 !important;
  }

  /* Overriding inline styles */
  [style] {
    background: #000 !important;
    color: #e0e0e0 !important;
  }

  /* Sidebars and containers */
  .sidebar, .side-bar, .sidenav, .left-panel, .right-panel,
  .menu, .navbar, .topbar, .header, .wrapper, .main, main,
  .content, .page, .container, .container-fluid, .app, #root {
    background: #000 !important;
    color: #e0e0e0 !important;
  }

  /* Cards and panels */
  .card, .panel, .box, .module, .section, .widget {
    background: #111 !important;
    color: #fff !important;
    box-shadow: none !important;
  }

  /* Inputs and buttons */
  input, textarea, select, button {
    background: #1a1a1a !important;
    color: #fff !important;
    border: 1px solid #444 !important;
  }

  /* Links */
  a { color: #64b5f6 !important; }
  a:hover { color: #90caf9 !important; }

  /* Scrollbars */
  ::-webkit-scrollbar { width: 10px; background: #000; }
  ::-webkit-scrollbar-thumb { background: #333; border-radius: 5px; }

  /* Selection */
  ::selection { background: #64b5f6 !important; color: #000 !important; }

  /* Images/videos slightly dimmed */
  img, video { filter: brightness(0.8) contrast(1.1) !important; }
}
